  #muruguard-root .bottom-0 { bottom:0; }
  #muruguard-root .left-0 { left:0; }
  #muruguard-root .z-50 { z-index:50; }
  #muruguard-root .z-\[9999\] { z-index:9999; }
  #muruguard-root .w-full { width:100%; }
