                <?php
                // Routed through com_ajax (plg_muruguardshield's
                // onAjaxMuruguardshield() bridge), NOT a direct
                // option=com_muruguard hit -- Joomla core's
                // AdministratorApplication::findOption() only lets a
                // GUEST request reach option=com_login or option=com_ajax,
                // silently redirecting anything else (including
                // com_muruguard itself) to the login page before a real,
                // unauthenticated external cron caller ever reaches
                // scheduledcheck()'s own token check. See
                // onAjaxMuruguardshield()'s own docblock for the full
                // explanation.
                //
                // Joomla 3 difference: com_ajax there is a FRONTEND
                // component, and the Joomla 3 administrator sends every
                // signed-out visitor to the login screen before com_ajax
                // ever runs -- so the cron URL points at the site
                // frontend instead of /administrator (the bridge itself
                // is identical, and scheduledcheck()'s own token check
                // still guards it; no &format= is passed so com_ajax
                // takes its default output path, which the bridge never
                // reaches anyway since scheduledcheck() closes the app).
                $webcronBase = MuruguardCompat::isJoomla4()
                    ? Uri::root() . 'administrator/index.php?option=com_ajax&plugin=muruguardshield&group=system&format=raw&token='
                    : Uri::root() . 'index.php?option=com_ajax&plugin=muruguardshield&group=system&token=';
                $webcronUrl = $webcronBase . $this->cronToken;
                ?>
                <div class="mb-5">
                    <label class="block text-xs font-bold text-gray-600 mb-1.5"><?= Text::_('COM_MURUGUARD_WEBCRON_URL_LABEL') ?> <span class="font-normal text-gray-400"><?= Text::_('COM_MURUGUARD_WEBCRON_URL_HINT') ?></span></label>
                    <div class="flex items-center gap-2 bg-gray-50 border border-gray-200 rounded-lg px-3 py-2">
